"""SOP assignment for sources uploaded from a sheet, with the Xtrium SOP documents bundled; default escalation reasons. Run from the repo root (the folder that holds backend/ and frontend/).
Safe to run twice: files already applied are skipped."""
import os, sys, zlib, base64
sys.stdout.reconfigure(errors='replace')
NEW = {'backend/app/services/sop_library.py': '', 'backend/app/api/v1/routes/sop_assign.py': '', 'frontend/src/pages/SopAssign.tsx': '', 'frontend/src/api/sopAssign.ts': '', 'backend/app/data/sops/SOP-DS-002.md': '', 'backend/app/data/sops/SOP-DS-003.md': '', 'backend/app/data/sops/SOP-DS-004.md': '', 'backend/app/data/sops/SOP-DS-005.md': '', 'backend/app/data/sops/SOP-DS-006.md': '', 'backend/app/data/sops/SOP-DS-007.md': '', 'backend/app/data/sops/SOP-DS-008.md': '', 'backend/app/data/sops/SOP-DS-009.md': '', 'backend/app/data/sops/SOP-DS-010.md': '', 'backend/app/data/sops/SOP-DS-011.md': '', 'backend/app/data/sops/SOP-DS-012.md': '', 'backend/app/data/sops/SOP-DS-013.md': '', 'backend/app/data/sops/SOP-DS-014.md': ''}
MOD = {'backend/app/main.py': [('    auth, users, projects, jobs, records, schemas,\n    submission, project_resources, work_submissions, sources,\n    integrations, notifications, enhancements, quality, observations,\n)\n', '    auth, users, projects, jobs, records, schemas,\n    submission, project_resources, work_submissions, sources,\n    integrations, notifications, enhancements, quality, observations, sop_assign,\n)\n'), ('app.include_router(quality.router,                          prefix=PREFIX)\napp.include_router(observations.router,                     prefix=PREFIX)\n\n', 'app.include_router(quality.router,                          prefix=PREFIX)\napp.include_router(observations.router,                     prefix=PREFIX)\napp.include_router(sop_assign.router,                       prefix=PREFIX)\n\n')], 'backend/app/services/sop_requirements.py': [('                     "fields": len(out["fields"]), "required_fields": sum(1 for f in out["fields"] if f["required"] and not f.get("nested")), "fields_with_allowed_values": sum(1 for f in out["fields"] if f["allowed"]),\n                     "warnings": len(w)}\n    return out\n', '                     "fields": len(out["fields"]), "required_fields": sum(1 for f in out["fields"] if f["required"] and not f.get("nested")), "fields_with_allowed_values": sum(1 for f in out["fields"] if f["allowed"]),\n                     "warnings": len(w)}\n    if meta.get("origin") == "library":\n        # Assigned from Xtrium\'s SOP documents because the source was not pulled from Xtrium: shown for reference, not enforced.\n        out["fields"], out["required_fields"] = [], []\n        out["counts"].update({"fields": 0, "required_fields": 0, "fields_with_allowed_values": 0})\n        out["reference_only"] = True\n        w.insert(0, "This SOP was assigned from Xtrium\'s SOP documents because the source was not pulled from Xtrium. It is here to read; field-by-field checks start once Xtrium\'s own copy is attached.")\n    return out\n')], 'frontend/src/App.tsx': [("import { DeliveryPage } from '@/pages/Delivery'\nimport { ObservationsPage } from '@/pages/Observations'\nimport { InsightsPage } from '@/pages/Insights'\nimport { MessagesPage } from '@/pages/Messages'", "import { DeliveryPage } from '@/pages/Delivery'\nimport { ObservationsPage } from '@/pages/Observations'\nimport { SopAssignPage } from '@/pages/SopAssign'\nimport { InsightsPage } from '@/pages/Insights'\nimport { MessagesPage } from '@/pages/Messages'"), ('          <Route path="delivery" element={<RequireTeamLead><DeliveryPage /></RequireTeamLead>} />\n          <Route path="observations" element={<RequireTeamLead><ObservationsPage /></RequireTeamLead>} />\n          <Route path="audit" element={<RequireTeamLead><AuditTrailPage /></RequireTeamLead>} />\n', '          <Route path="delivery" element={<RequireTeamLead><DeliveryPage /></RequireTeamLead>} />\n          <Route path="observations" element={<RequireTeamLead><ObservationsPage /></RequireTeamLead>} />\n          <Route path="sop-assign" element={<RequireTeamLead><SopAssignPage /></RequireTeamLead>} />\n          <Route path="audit" element={<RequireTeamLead><AuditTrailPage /></RequireTeamLead>} />\n')], 'frontend/src/components/layout/AppLayout.tsx': [("  Users, Bell, LogOut, Settings, BookOpen, ChevronDown,\n  Menu, X, Shield, Activity, AlertTriangle,\n  Zap, ShieldCheck, HeartPulse, CircleHelp, MessageCircle, CalendarCheck, PackageCheck, ChartColumn, History, Search, PanelLeftClose, PanelLeftOpen, Sun, Moon, ClipboardList } from 'lucide-react'\nimport { cn, ToastContainer, toast } from '@/components/ui'\nimport { notificationsApi, sourcesApi } from '@/api/client'", "  Users, Bell, LogOut, Settings, BookOpen, ChevronDown,\n  Menu, X, Shield, Activity, AlertTriangle,\n  Zap, ShieldCheck, HeartPulse, CircleHelp, MessageCircle, CalendarCheck, PackageCheck, ChartColumn, History, Search, PanelLeftClose, PanelLeftOpen, Sun, Moon, ClipboardList, ListChecks } from 'lucide-react'\nimport { cn, ToastContainer, toast } from '@/components/ui'\nimport { notificationsApi, sourcesApi } from '@/api/client'"), ("    { to: '/quality',    icon: ShieldCheck,    label: 'Quality',      show: isTeamLead },\n    { to: '/observations', icon: ClipboardList, label: 'Observations', show: isTeamLead },\n    { to: '/data-health', icon: HeartPulse,      label: 'Data Health',  show: true, badge: counts.link_problems, badgeColor: '#d97706' },\n    { to: '/client-questions', icon: CircleHelp, label: 'Client Questions', show: true, badge: counts.open_questions, badgeColor: '#d97706' },", "    { to: '/quality',    icon: ShieldCheck,    label: 'Quality',      show: isTeamLead },\n    { to: '/observations', icon: ClipboardList, label: 'Observations', show: isTeamLead },\n    { to: '/sop-assign', icon: ListChecks, label: 'SOP assignment', show: isTeamLead },\n    { to: '/data-health', icon: HeartPulse,      label: 'Data Health',  show: true, badge: counts.link_problems, badgeColor: '#d97706' },\n    { to: '/client-questions', icon: CircleHelp, label: 'Client Questions', show: true, badge: counts.open_questions, badgeColor: '#d97706' },")], 'frontend/src/pages/SourceDetail.tsx': [("// A fresh page for every source, so stepping from one source to the next never carries over\n// the previous one's open tabs or half-finished edits.\nexport function SourceDetailPage() {\n  const { sourceId } = useParams<{ sourceId: string }>()", "// A fresh page for every source, so stepping from one source to the next never carries over\n// the previous one's open tabs or half-finished edits.\n/** Used when a project has not set its own escalation reasons. Taken from SOP-DS-003 (broken pages, login-only or confidential\n *  content, paywalls, wrong entity, schema gaps), so extractors are never stuck with an empty list. */\nconst DEFAULT_ESCALATION_REASONS = [\n  'Link is broken and no official alternate source exists',\n  'Page is blank or has nothing extractable',\n  'Needs a login or is confidential',\n  'Behind a paywall',\n  'Page does not match the expected company or item',\n  'Content does not fit the schema or SOP',\n  'Other (explain in the note)',\n]\n\nexport function SourceDetailPage() {\n  const { sourceId } = useParams<{ sourceId: string }>()"), ("      .then((r: any) => {\n        const list = Array.isArray(r) ? r : r?.items ?? []\n        setEscalationReasons(list.filter((res: any) => res.type === 'escalation_reason').map((res: any) => res.title))\n      })\n      .catch(() => setEscalationReasons([]))\n      .finally(() => setLoadingEscalationReasons(false))\n  }, [source?.project_id])", "      .then((r: any) => {\n        const list = Array.isArray(r) ? r : r?.items ?? []\n        const own = list.filter((res: any) => res.type === 'escalation_reason').map((res: any) => res.title)\n        setEscalationReasons(own.length ? own : DEFAULT_ESCALATION_REASONS)\n      })\n      .catch(() => setEscalationReasons(DEFAULT_ESCALATION_REASONS))\n      .finally(() => setLoadingEscalationReasons(false))\n  }, [source?.project_id])")]}
root = os.getcwd()
if not (os.path.isdir(os.path.join(root, 'backend')) and os.path.isdir(os.path.join(root, 'frontend'))):
    sys.exit('Run this from the repo root (the folder containing backend and frontend).')
def rd(p): return open(p, encoding='utf-8', newline='').read()
done = skipped = 0; bad = []
for rel, hunks in MOD.items():
    p = os.path.join(root, rel)
    if not os.path.exists(p): bad.append(rel + ' (missing)'); continue
    raw = rd(p); crlf = '\r\n' in raw; t = raw.replace('\r\n', '\n'); changed = False
    for old, new in hunks:
        if new in t: continue
        elif t.count(old) == 1: t = t.replace(old, new); changed = True
        else: bad.append(rel + ' (a section does not match; file differs from expected version)'); break
    else:
        if changed:
            open(p, 'w', encoding='utf-8', newline='').write(t.replace('\n', '\r\n') if crlf else t); done += 1; print('updated ', rel)
        else: skipped += 1
for rel, blob in NEW.items():
    p = os.path.join(root, rel); data = zlib.decompress(base64.b64decode(blob))
    if os.path.exists(p) and open(p, 'rb').read() == data: skipped += 1; continue
    os.makedirs(os.path.dirname(p), exist_ok=True); open(p, 'wb').write(data); done += 1; print('wrote   ', rel)
print(f'\n{done} changed, {skipped} already applied.')
if bad:
    print('\nPROBLEMS:'); [print(' -', b) for b in bad]; sys.exit(1)
